package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionDaysLogsVO;

class RetentionDaysLogsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention days logs of observability config")
  void test_retention_days_logs_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionDaysLogsValueHolder<Object> value = new RetentionDaysLogsValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionDaysLogs(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysLogsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionDaysLogs().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention days logs of observability config")
  void test_retention_days_logs_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionDaysLogsValueHolder<Object> value = new RetentionDaysLogsValueHolder<>(holder);
    RetentionDaysLogsVO vo = RetentionDaysLogsVO.from(1);
    Assertions.assertFalse(value.getRetentionDaysLogsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionDaysLogs(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionDaysLogsValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionDaysLogs(Optional.empty()));
    Assertions.assertFalse(value.getRetentionDaysLogsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionDaysLogs(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionDaysLogsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention days logs of observability config against the original")
  void test_retention_days_logs_value_holder_read() {
    Object holder = new Object();
    RetentionDaysLogsValueHolder<Object> value = new RetentionDaysLogsValueHolder<>(holder);
    RetentionDaysLogsVO vo = RetentionDaysLogsVO.from(1);
    RetentionDaysLogsVO other = RetentionDaysLogsVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionDaysLogsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionDaysLogs(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionDaysLogs(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionDaysLogs(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionDaysLogs(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionDaysLogs(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention days logs of observability config")
  void test_retention_days_logs_value_holder_unset() {
    Object holder = new Object();
    RetentionDaysLogsValueHolder<Object> value = new RetentionDaysLogsValueHolder<>(holder);
    RetentionDaysLogsVO vo = RetentionDaysLogsVO.from(1);
    value.retentionDaysLogs(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysLogsIfMatches("retentionDaysLogs_other"));
    Assertions.assertTrue(value.getRetentionDaysLogsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionDaysLogsIfMatches("retentionDaysLogs"));
    Assertions.assertFalse(value.getRetentionDaysLogsValue().isPresent(),
        "The field name must clear the value");
    value.retentionDaysLogs(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysLogs());
    Assertions.assertFalse(value.getRetentionDaysLogsValue().isPresent(),
        "Unset must clear the value");
  }
}
